    function parsePath(path) { return path.match(/[^.\[\]]+/g) || []; }
    function SafeGetValue(obj, path, defaultValue = "N/A") { const keys = parsePath(path); let current = obj; for (const key of keys) { if (current === undefined || current === null) return defaultValue; if (/\\d+/.test(key) && Array.isArray(current)) { current = current[parseInt(key)]; } else if (typeof current === 'object' && current.hasOwnProperty(key)) { current = current[key]; } else { return defaultValue; } } return current ?? defaultValue; }

    function updateProgressBar(barId, rawValue, min, max, textId, textMap) { 
        const progressBar = document.getElementById(barId); 
        if (!progressBar) return; 
        let numericValue = parseFloat(rawValue); 
        if (isNaN(numericValue)) numericValue = min; 
        numericValue = Math.max(min, Math.min(max, numericValue)); 
        const percentage = max - min === 0 ? 100 : ((numericValue - min) / (max - min)) * 100; 
        progressBar.style.width = `${percentage}%`; 
        if(textId && textMap) { 
            const textElement = document.getElementById(textId); 
            if(textElement) { 
                let stage = textMap.default; 
                for(const threshold of Object.keys(textMap.stages).sort((a,b) => a-b)) { 
                    if(numericValue >= parseInt(threshold)) { 
                        stage = textMap.stages[threshold]; 
                    } 
                } 
                textElement.innerText = `${stage} (${rawValue})`; 
            } 
        } 
    }

    function getMartialLevelClass(value) {
        if (value >= 800) return 'level-legend';
